function generateSliderImages(e,t,a){function n(){l=(l+1)%d,i.style.transform=`translateX(-${100*l}%)`}let l=0;const r=4,d=Math.ceil(a/r),i=document.getElementById(t);i.innerHTML="";for(let t=0;t<a;t+=r){const n=document.createElement("div");n.className="image-slider-slide-image-container";for(let l=0;l<r&&t+l<a;l++){const a=document.createElement("div");a.className="image-slider-slide-image";const r=document.createElement("img");r.src=e+`image${t+l+1}.jpg`,r.alt=`image${t+l+1}`,r.loading="lazy",a.appendChild(r),n.appendChild(a)}i.appendChild(n)}setInterval(n,5e3)}async function loadImageSlider(){try{const e=document.querySelectorAll(".image-slider-placeholder");e.forEach(async e=>{const t=await fetch("/assets/components/image-slider.html"),a=await t.text(),n=e.dataset.id,l=e.dataset.folder,r=parseInt(e.dataset.numberOfImages);e.innerHTML=a;const d=e.querySelector(".image-slider-track");d.id=n,generateSliderImages(l,n,r)})}catch(e){console.error("Error loading title:",e)}}document.addEventListener("DOMContentLoaded",loadImageSlider);